from typing import List

def max_k_valid_paths(n: int) -> List[int]:
    # Initialize the dp array where dp[i][j] is the maximum number of k-valid paths with i nodes out of 1 to i, for j values of k.
    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    arr = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # Initialize the first row of dp
    for i in range(1, n + 1):
        dp[1][i] = 1

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            for k in range(1, j + 1):
                if arr[i][j] == i:
                    dp[i][j] = max(dp[i][j], dp[j][k] + dp[k][j] - dp[k - 1][k] + dp[k - 1][j - 1] if k != j else 1)
                else:
                    dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j])

    # Fill the array for arr[*,*]
    arr[1][1] = 2
    for i in range(1, n + 1):
        arr[i][0] = arr[i][i] = i

    # Fill the arithmetic array
    for i in range(2, n + 1):
        for j in range(1, i):
            arr[i][j] = min(arr[i - 1][j], arr[i][j - 1]) + 1

    # Print the results
    return [dp[n][k] for k in range(1, n + 1)]

