class BracketSequence:
    def __init__(self, pattern):
        self.pattern = pattern
        self.cost = {}
        self.equivalent_sequences = {}

    def find_equivalent_sequences(self, cost, index):
        if index == len(pattern):
            return [self.pattern]
        if (index, cost) in self.equivalent_sequences:
            return self.equivalent_sequences[(index, cost)]

        options = ['(', ')']
        sequences = []
        for option in options:
            substring_pattern = self.pattern[index:]
            new_index = pattern.find(option, index)
            if new_index == -1:
                continue
            new_pattern = pattern[:index] + option + self.pattern[index+1:]
            cost_of_substitution_under_deleted_input = self.cost.get((index, option), 0)
            new_cost = cost + cost_of_substitution_under_deleted_input
            for sequence in self.find_equivalent_sequences(new_cost, new_index):
                sequences.append(new_pattern[0] + new_pattern[1:] + sequence)

        self.equivalent_sequences[(index, cost)] = sequences
        return sequences

    def find_least_expensive_solution(self):
        mind = [float('inf')] * len(self.pattern)
        mind[0] = self.cost.get((0, self.pattern[0]), 0)
        for i in range(1, len(self.pattern)):
            target_cost, a, b, min_cost = mind[i-1], self.cost.get((i, self.pattern[i]), 0), 0, float("inf")
            if target_cost < mind[i-1]:
                a, b = 0, 1
            elif a > mind[i-1]:
                a, b = 1, 0
            if target_cost - mind[i-1] == 1:
                mind[i], min_cost = mind[i-1], mind[i]
            for j in range(min(i, a), min(len(self.pattern), b)):
                mind[i] = min(mind[i], self.cost.get((i, target_cost), 0) + mind[j])
            if mind[i] == float('inf'):
                return -1
        return mind[-1]

def solve(pattern, costs):
    sequence = BracketSequence(pattern)
    print(sequence.find_least_expensive_solution())

