from collections import defaultdict

def bellman_ford(graph, s, t):
    n = len(graph)
    dist = defaultdict(lambda: {'inf': 0, 'u': 'inf', 'v': 'inf'})
    dist[s]['inf'] = 0

    # Relax all edges |V - 1| times
    for _ in range(n - 1):
        update = False
        for u in range(n):
            for v, w in graph[u].items():
                if dist[u]['inf'] + w < dist[v]['inf']:
                    dist[v]['inf'] = dist[u]['inf'] + w
                    update = True
        if update:
            update = False
            for u in range(n):
                for v, w in graph[u].items():
                    if dist[u]['inf'] + w < dist[v]['inf']:
                        dist[v]['inf'] = dist[u]['inf'] + w
                        update = True
        if not update:
            break

    # Relax all edges one more time to check for negative weight cycles
    for _ in range(n - 1):
        update = False
        for u in range(n):
            for v, w in graph[u].items():
                if dist[u]['inf'] + w < dist[v]['inf']:
                    dist[v]['inf'] = dist[u]['inf'] + w
                    update = True
        if update:
            update = False
            for u in range(n):
                for v, w in graph[u].items():
                    if dist[u]['inf'] + w < dist[v]['inf']:
                        dist[v]['inf'] = dist[u]['inf'] + w
                        update = True
        if not update:
            return -1

    return dist[t], len(dist[t]['inf'])

