def find_cycle_length(b):
    """Finds the length of the repeating cycle in b."""
    if all(b[i] == 0 for i in range(len(b))):
        return 0
    next = {0: 0}
    for i in range(len(b)):
        if not next.get(b[i], -1) == i:
            end = i
            found_cycle = False
            while not found_cycle:
                b_to_find = next.get(end, 0)
                if b_to_find == 0:
                    found_cycle = False
                elif b_to_find not in next:
                    next[b_to_find] = b[end]
                    end = b_to_find
                else:
                    found_cycle = True
                    repetitions = (len(b) - end) // (i - next[b_to_find])
                    break
            if found_cycle:
                break
        else:
            next[b[i]] = i
    return found_cycle

def is_possible(a, b):
    """Checks if a cyclic array a can produce the given b."""
    n = len(a)
    if any(b[i] == 0 for i in range(n)):
        return False
    length_of_cycle = find_cycle_length(b)
    for i in range(n):
        b[i] %= a[i + 1]
    if not (1 <= min(b) <= max(b) <= 10**18) or max(b) + 1 != len(b):
        return False
    if length_of_cycle != ((n - 1) % (length_of_cycle + 1)):
        return False
    for i in range(n):
        if (i + 1) % (length_of_cycle + 1) != (b[i] * n) % (length_of_cycle + 1):
            return False
    return True

def restore_a(b):
    """Finds a cyclic array a that produces the given b."""
    n = len(b)
    length_of_cycle = find_cycle_length(b)
    repetitions = (n - 1) % (length_of_cycle + 1)
    tail = 0
    if (length_of_cycle + 1) % 2 == 0:
        tail = (n - 1) // ((length_of_cycle + 1) // 2)
    rep = min(length_of_cycle + 1, repetitions)
    remaining = n % ((length_of_cycle + 1) // 2)
    phase = (tail + rep + remaining - 1) % ((length_of_cycle + 1) % 2)
    mid = phase + (repetitions - rep) // 2
    return [(a[0] if i == 0 else b[(n - 1 - i) % (length_of_cycle + 1) % 2] * n if i == mid else tail) for i in range(n)]

def solve():
    n = int(input().strip())
    b = list(map(int, input().strip().split()))
    a = restore_a(b)
    if all(1 <= i <= 10**18 for i in a):
        print("YES")
        print(" ".join(map(str, a)))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
