def maxLineRank(n, relations):
    # Prefix sums array
    sumCounts = [0]
    counts = {i: 0 for i in range(1, n + 1)} # Mapping indices to 0 initially

    for _, nextIndex in relations:
        sumCounts.append(sumCounts[-1] + 1)
        for cond in reversed(range(50)): # We search backwards, number of prefixes of length k
            lo, hi = sumCounts[0], sumCounts[50]
            while hi - lo > 1:
                mi = (lo + hi) // 2 
                if counts[mi] <= 2:
                    low = mi
                else:
                    if sumCounts[mi] >= counts[nextIndex]:
                        low = mi
                    else:
                        hi = mi 
            if low < hi:
                if counts[low] > 2:
                    if sumCounts[hi] < counts[nextIndex]:
                        counts[nextIndex] = min(sumCounts[hi], counts[nextIndex])
                    else:
                        counts[nextIndex] = min(counts[nextIndex], sumCounts[hi] + 1)

