def count_minimum_lines(n, relations):
    # Create a list where each element references the next piece it can follow
    next_possibilities = [-1] * n

    for rel in relations:
        next_possibilities[rel[0] - 1] = rel[1] - 1

    current_line = 0
    lines = []

    while current_line < n:
        lines.append(n - current_line)  # Line length determines if relationship can be built
        current_line += lines[-1]

        for i in range(n - 1, current_line - 1, -1):
            if next_possibilities[i] >= 0 and lines[-1] - lines[-2] != next_possibilities[i] - lines[-2]:
                lines[-1] = lines[-2]
                break

    return sum(lines)

