def max_valid_paths(n, adj_list):
    # Memoization dictionary to store the number of valid paths ending at each node
    memo = {i: 0 for i in range(1, n + 1)}
    # Initialize the number of valid paths for the first vertex
    memo[1] = 1

    # Iterate through each vertex
    for i in range(1, n):
        prev = -1
        current = i
        # Iterate through the neighbors of the current vertex
        while current in adj_list:
            j = adj_list[current].pop() if adj_list[current].pop() != prev else len(adj_list[current]) - 1
            if j == current or j == prev:
                memo[i] = max(memo[i], memo[j] + 1)
            else:
                memo[i] = max(memo[i], memo[j] + memo[j])
            prev = current
            current = j
    return list(map(memo.get, range(1, n + 1)))

