def is_stongly_connected_by_edges(edges):
    n = len(edges)
    clockwise = [False] * n
    anti_clockwise = [False] * n

    for i in range(n):
        for j in range(i):
            if edges[i][j]:
                clockwise[j] = True
            if edges[j][i]:
                anti_clockwise[i] = True

    for i in range(n):
        for j in range(i):
            if clockwise[i] ^ anti_clockwise[j]:
                return False
    return True

def min_operations_to_stongly_connected(edges, key_edge):
    n = len(edges)
    operations = 0

    while not is_stongly_connected_by_edges(edges):
        # Color the edges in a circular manner, start from the most critical edge
        color = key_edge + 1
        for i in range(n):
            edges[i][color] = False
            edges[color][i] = True

        connected_components = [color]

        for i in range(n):
            for j in range(i+1, n):
                if edges[i][j] and not connected_components[j]:
                    connected_components.append(j)
                    for k in range(j+1, n):
                        if edges[k][j] and not connected_components[k]:
                            connected_components.append(k)

        operations += len(connected_components) - 1
        edge_color_connected = defaultdict(int)
        for i in range(n):
