import sys
from collections import defaultdict, deque

def dijkstra(graph, start):
    n = len(graph)
    # Queue to hold tuples (time, city)
    q = [(0, start)]
    # Array to hold the shortest distance from start
    dist = [float('inf')] * n
    dist[start] = 0
    # Keep track of visited nodes
    seen = set()

    while q:
        time, city = q[0]
        q = q[1:]

        if time > dist[city]:
            continue

        if city in seen:
            continue

        seen |= {city}

        for neighbor, weight in graph[city].items():
            new_time = time + weight
            if new_time < dist[neighbor]:
                dist[neighbor] = new_time
                q.append((new_time, neighbor))
                if neighbor not in seen:
                    q = deque(sorted(q, key=lambda x: x[0]))

    return dist


def max_unhappy_friends(n, m, start, roads):
    graph = defaultdict(dict)

    for u, v, w in roads:
        graph[u][v] = w
        graph[v][u] = w

    unvisited = {i for i in range(1, n+1)}
    visited = set()

    # Initialize dist[A][start]
    dist = {i: [float('inf')] * i for i in range(n)}

    for i in range(1, n+1):
        initial_distances = dijkstra(graph, i)
        # Update smallest distances that not visited
        dist[i] = {j: min(dist[j][k] for k in range(n) if i != j) for j in unvisited - {i}}
        unvisited -= {i}

    # Calculate the number of unhappy friends
    unhappy_friends = sum(dist[i] == float('inf') for i in unvisited - visited)

    for u, v, w in roads:
        if u in unvisited and v in unvisited:
            if dist[u][v] == float('inf'):
                unhappy_friends -= 1

    return unhappy_friends


