from heapq import heappush, heappop

def build_graph(pattern, costs):
    n = len(pattern)
    graph = [[] for _ in range(n)]
    for i in range(n):
        cost1 = 1000000000 if pattern[i] == '?' else costs[0]
        cost2 = 1000000000 if pattern[i] == '?' else costs[1]
        if (i == 0 or pattern[i-1] != '?'):
            graph[i].append((-cost2, (i+2, -i)))
        graph[i].append((-cost1, (i-1, i)))

    return graph

def find_min_path(graph):
    n = len(graph)
    heap = [(0, 0, 0)]
    visited = [1000000000] * n
    visited[0] = 0
    initial_cost = 0
    minimum_cost = cost1, cost2

    while heap:
        current_cost, vertex, parent = heappop(heap)
        if vertex == n-1:
            return current_cost
        if visited[vertex] < current_cost:
            continue
        for next_cost, child in graph[vertex]:
            new_cost = current_cost + next_cost
            if new_cost < visited[child]:
                visited[child] = new_cost
                if initial_cost + next_cost < minimum_cost:
                    new_cost += initial_cost
                    heappush(heap, (new_cost, child, vertex))
                elif visited[child] > new_cost:
                    heappush(heap, (new_cost, child, vertex))

    return minimum_cost

def solve(pattern, costs):
    if costs[0] > costs[1]:
        costs = costs[::-1]
    graph = build_graph(pattern, costs)
    return find_min_path(graph)

