from collections import deque

def min_cost_sequence(pattern, costs):
    """
    Finds the minimum cost for brackets sequence replacement based on given costs.

    Args:
    pattern (str): The original pattern of the bracket sequence.
    costs (list): A list of costs for replacing each '?' with '(' and ')'.

    Returns:
    str: The optimized regular bracket sequence.
    int: The total minimum cost.
    """
    n = len(pattern)
    dp = [[float('inf')] * 2 for _ in range(n)]
    dp[0][0] = 0  # No cost to open a bracket
    dp[0][1] = costs[0][0] if pattern[0] == '?' else costs[0][1]  # Cost to open '(' or ')'

    for i in range(1, n):
        dp[i][0] = dp[i-1][0]  # No absense, take value from cost
        for j in range(1, 2):
            if j == 0 and pattern[i] != '?':
                dp[i][j] = dp[i-1][j]  # No parentheses so we also don't open any more
            else:
                dp[i][j] = dp[i-1][j-1] + costs[i][j] if pattern[i] == '?' else dp[i-2][j] + costs[i][j-1]
            dp[i][j] = min(dp[i][j], dp[i][j-1] + dp[i-3][1])

    def backtrack(index):
        if index == n:
            return []

        for j in (0, 1):
            if j == 0 and pattern[index] == '?':
                cost_open = dp[index][0]
                cost_close = dp[index][1]
                break
        if cost_open + cost_close > dp[index][0]:
            return backtrack(index + 1)

        open_pre = cost_open if pattern[index] == '(' else cost_open + dp[index-1][1]
        close_pre = cost_close

        if backtrack(index + 1):
            return backtrack(index + 1)
        if open_pre + backtrack(index + 2) < close_pre + backtrack(index):
            return [pattern[:index] + '(' + backtrack(index)[0:-1] + ')' + pattern[index:], ')' + backtrack(index)[0:-1] + ']']
        else:
            return [pattern[:index] + ']' + backtrack(index)[0:-1] + pattern[index:], '(' + backtrack(index)[0:-1] + ']']

    sequences = backtrack(n)
    if not sequences:
        return -1

    return format(sequences, "()"))

def format(seq, brackets):
    """Format the bracket sequence"""
    return brackets.format(seq)

