# Game parameters
mod = 998244353

# Function to calculate the number of ways to achieve a strongly connected graph
def calculate_ways(vertices, edges):
    num_ways = 1
    for i in range(1, vertices):
        num_ways = (num_ways * 2) % mod
    return num_ways

# Function to determine if the graph can be made strongly connected with the given operations
def can_be_strongly_connected(vertices, nedges, graph, edges):
    pi = [-1] * vertices
    q = collections.deque()
    budget = collections.defaultdict(int)

    for v in range(0,vertices):
        if graph[v] == []:
            budget[v] -= 1
            q.append(v)

    while q:
        v = q.popleft()
        for e in graph[v]:
            if budget[e] <= 0:
                continue
            pi[e] = v
            budget[e] -= 1
            if e == q[0]:
                q.popleft()
            else:
                q.append(e)
    start = (pi[edges[0]] ^ 1)
    if start != edges[0]:
        return -1  # Not strongly connected
    budget = collections.defaultdict(int)
    q = collections.deque()
    for v in range(0,vertices):
        if v != edges[0]:
            q.append(v)
        budget[v] -= 1

    while q:
        v = q.popleft()
        for e in graph[v]:
            if budget[e] <= 0 or pi[e] == e:
                continue
            pi[e] = v
            budget[e] -= 1
            if e == q[0]:
                q.popleft()
            else:
                q.append(e)
    if pi[edges[0]] != edges[0]:
        return -1  # Not strongly connected
    budget = collections.defaultdict(int)
    for v in range(0,vertices):
        q.append(v)
        budget[v] -= 1

    while q:
        v = q.popleft()
        for e in graph[v]:
            if v == e:
                continue
            elif budget[e] <= 0:
                continue
            elif e == q[0]:
                budget[e] -= 1
                q.popleft()
            else:
                budget[e] -= 1
                q.append(e)
        if v in budget and budget[v] <= 0:
            return -1  # Not strongly connected

    return 1  # Can be made strongly connected

