def find_min_lines(N, M, relations):
    graph = {i: [] for i in range(1, N + 1)}
    for A, B in relations:
        graph[A].append(B)

    visited = [False] * (N + 1)
    def dfs(node):
        if visited[node]:
            return 1
        visited[node] = True
        return sum(dfs(B) for B in graph[node]) + 1

    min_lines = float('inf')
    for node in range(1, N + 1):
        if not visited[node]:
            min_lines = min(min_lines, dfs(node))

    return min_lines

